    /**
 * 整体覆盖原 OSS 对象并同步 size
 * @summary 保存文本内容
 */
export const postFileContentSave = (
    fileContentSaveReq: MaybeRefOrGetter<FileContentSaveReq>,
 signal?: AbortSignal
) => {
      fileContentSaveReq = toValue(fileContentSaveReq);

      return customInstance<FileNodeVO>(
      {url: `/api/file/content/save`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: fileContentSaveReq, signal
    },
      );
    }




export const getPostFileContentSaveMutationKey = () => ['postFileContentSave'] as const;

export const getPostFileContentSaveMutationOptions = <TError = unknown,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof postFileContentSave>>, TError,PostFileContentSaveMutationVariables, TContext>, }
): UseMutationOptions<Awaited<ReturnType<typeof postFileContentSave>>, TError,PostFileContentSaveMutationVariables, TContext> => {

const mutationKey = getPostFileContentSaveMutationKey();
const {mutation: mutationOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof postFileContentSave>>, PostFileContentSaveMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  postFileContentSave(data,)
        }






  return  { mutationFn, ...mutationOptions }}

    export type PostFileContentSaveMutationResult = NonNullable<Awaited<ReturnType<typeof postFileContentSave>>>
    export type PostFileContentSaveMutationBody = FileContentSaveReq
    export type PostFileContentSaveMutationError = unknown
    export type PostFileContentSaveMutationVariables = {data: FileContentSaveReq}

    /**
 * @summary 保存文本内容
 */
export const usePostFileContentSave = <TError = unknown,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof postFileContentSave>>, TError,PostFileContentSaveMutationVariables, TContext>, }
 , queryClient?: QueryClient): UseMutationReturnType<
        Awaited<ReturnType<typeof postFileContentSave>>,
        TError,
        PostFileContentSaveMutationVariables,
        TContext
      > => {
      return useMutation(getPostFileContentSaveMutationOptions(options), queryClient);
    }
